package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

type PathError struct {
	Op   string
	Path string
	Err  error
}

func (e *PathError) Error() string { return e.Op + " " + e.Path + ": " + e.Err.Error() }
func (e *PathError) Unwrap() error { return e.Err }

type codeError struct{ code int }

func (c codeError) Error() string { return fmt.Sprintf("code %d", c.code) }

func open(p string) error {
	return &PathError{"open", p, fmt.Errorf("layer: %w", ErrNotFound)}
}

func main() {
	err := open("/tmp/x")
	fmt.Println(err)
	fmt.Println(errors.Is(err, ErrNotFound))
	fmt.Println(errors.Is(err, errors.New("not found")))
	fmt.Println(errors.Unwrap(err))
	fmt.Println(errors.Unwrap(errors.Unwrap(err)) == ErrNotFound)

	var pe *PathError
	fmt.Println(errors.As(err, &pe), pe.Op, pe.Path)

	var ce codeError
	fmt.Println(errors.As(err, &ce))

	wrapped := fmt.Errorf("outer: %w", &PathError{"stat", "/y", ErrNotFound})
	fmt.Println(wrapped)
	fmt.Println(errors.Is(wrapped, ErrNotFound), errors.As(wrapped, &pe), pe.Op)

	plain := fmt.Errorf("no verb %v", ErrNotFound)
	fmt.Println(errors.Is(plain, ErrNotFound), errors.Unwrap(plain) == nil)
	fmt.Println(errors.Is(nil, nil), errors.Is(ErrNotFound, nil))
}

