package main

import (
	"errors"
	"fmt"
)

var ErrTimeout = errors.New("timeout")
var ErrClosed = errors.New("closed")

// netError reports itself equal to ErrTimeout when it timed out, without
// wrapping it: errors.Is must consult the Is method.
type netError struct {
	op      string
	timeout bool
}

func (e *netError) Error() string { return "net " + e.op }
func (e *netError) Is(target error) bool {
	return target == ErrTimeout && e.timeout
}

// codeError matches any codeError with the same code.
type codeError struct{ code int }

func (c codeError) Error() string { return fmt.Sprintf("code %d", c.code) }
func (c codeError) Is(target error) bool {
	t, ok := target.(codeError)
	return ok && t.code == c.code
}

type layer struct {
	name string
	err  error
}

func (l *layer) Error() string { return l.name + ": " + l.err.Error() }
func (l *layer) Unwrap() error { return l.err }

func main() {
	slow := &netError{"dial", true}
	fast := &netError{"read", false}
	fmt.Println(errors.Is(slow, ErrTimeout), errors.Is(fast, ErrTimeout))
	fmt.Println(errors.Is(slow, ErrClosed), errors.Is(slow, slow), errors.Is(fast, slow))

	w := fmt.Errorf("request: %w", &layer{"conn", slow})
	fmt.Println(w)
	fmt.Println(errors.Is(w, ErrTimeout), errors.Is(w, ErrClosed))

	c := fmt.Errorf("op: %w", codeError{404})
	fmt.Println(errors.Is(c, codeError{404}), errors.Is(c, codeError{500}))
	fmt.Println(errors.Is(codeError{7}, codeError{7}), errors.Is(codeError{7}, ErrTimeout))

	var ne *netError
	fmt.Println(errors.As(w, &ne), ne.op, ne.timeout)
}

