// Test simulating a Turing machine, sort of.

package main

// brainfuck

var p, pc int
var a [30000]byte

const prog = "++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------.>+.>.!"

func scan(dir int) {
	for nest := dir; dir*nest > 0; pc += dir {
		switch prog[pc+dir] {
		case ']':
			nest--
		case '[':
			nest++
		}
	}
}

func main() {
	r := ""
	for {
		switch prog[pc] {
		case '>':
			p++
		case '<':
			p--
		case '+':
			a[p]++
		case '-':
			a[p]--
		case '.':
			r += string(a[p])
		case '[':
			if a[p] == 0 {
				scan(1)
			}
		case ']':
			if a[p] != 0 {
				scan(-1)
			}
		default:
			if r != "Hello World!\n" {
				panic(r)
			}
			return
		}
		pc++
	}
}

package main

func init() {
	v := []int{458959, -1016755, 321130, -162090, 273225, 799512, -115369, -714331}
	m := map[int]int{}
	s := 58550
	for i, x := range v {
		m[i] = x ^ (s << 1)
		s = s*131 + x + len(m)
	}
	f := func(k int) int { return m[k] + k*71 }
	for i := range v {
		s ^= f(i)
	}
	t := ""
	for _, x := range v {
		if x&1 == 0 {
			t += "e"
		} else {
			t += "o"
		}
	}
	println("wit", s, t, len(m))
}

