func TestTable(t *testing.T) {
	cases := []struct {
		name       string
		a, b, want int
	}{
		{"zero", 0, 0, 0},
		{"pos", 2, 3, 5},
		{"neg", -1, 1, 0},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := Add(c.a, c.b); got != c.want {
				t.Errorf("Add(%d,%d) = %d, want %d", c.a, c.b, got, c.want)
			}
			t.Run("double", func(t *testing.T) {
				if Mul(c.want, 2) != c.want*2 {
					t.Errorf("Mul broken")
				}
			})
		})
	}
}

